import{_ as t,o as a,c as o,aj as n}from"./framework.js";const g=JSON.parse('{"title":"k.paramConfig | Param Config | KScript API","description":"Read the structured JSON data saved in the background Content → Parameter Configuration","frontmatter":{"title":"k.paramConfig | Param Config | KScript API","description":"Read the structured JSON data saved in the background Content → Parameter Configuration","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/api/param-config/index.html"}]]},"headers":[],"relativePath":"api/param-config/index.md","filePath":"en/api/param-config/index.md","lastUpdated":1792999452000}'),i={name:"api/param-config/index.md"};function s(r,e,d,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="k-paramconfig" tabindex="-1">k.paramConfig <a class="header-anchor" href="#k-paramconfig" aria-label="Permalink to &quot;k.paramConfig&quot;">​</a></h1><blockquote><p>Read the structured JSON data saved in the background <strong>Content → Parameter Configuration</strong></p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>k.paramConfig</code> reads the data saved in the background <strong>Content → Parameter Configuration</strong>: each configuration has <strong>name</strong> (<code>name</code>), <strong>display name</strong>, <strong>Schema</strong> (field structure) and <strong>data</strong> (JSON value). Access according to configuration name and field name in Page, Layout, View or KScript. There is no need to write phone numbers, switches, link objects, etc. in the template.</p><p>See <a href="/kb-docs/cms/content/user-options.html">Param Config</a> for background maintenance methods.</p><div class="tip custom-block"><p class="custom-block-title">Differences from other APIs</p><table tabindex="0"><thead><tr><th>API</th><th>Purpose</th></tr></thead><tbody><tr><td><strong><code>k.paramConfig</code></strong></td><td>This page: Site-level JSON parameters defined by Schema</td></tr><tr><td><strong><code>k.label</code> / <code>k.t</code></strong></td><td>Multilingual short copy, see <a href="/kb-docs/api/label/">k.label</a></td></tr><tr><td><strong><code>k.content</code></strong></td><td>Content folder entry fields, see <a href="/kb-docs/api/content/">k.content</a></td></tr><tr><td><strong>Element Properties (KConfig)</strong></td><td>HTML attributes bound by template <code>k-config</code>, see <a href="/kb-docs/cms/content/tag-attributes.html">Tag Attributes</a></td></tr></tbody></table></div><h2 id="access-method" tabindex="-1">Access method <a class="header-anchor" href="#access-method" aria-label="Permalink to &quot;Access method&quot;">​</a></h2><h3 id="recommended-property-access" tabindex="-1">Recommended Property Access <a class="header-anchor" href="#recommended-property-access" aria-label="Permalink to &quot;Recommended Property Access&quot;">​</a></h3><p>The <strong>name</strong> configured in the background is used as the first-level attribute of <code>k.paramConfig</code>; the field name in the Schema is used as the attribute below it (objects can continue to be nested).</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Config name: siteContact; Schema contains phone and showBanner</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> phone </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> k.paramConfig.siteContact.phone;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> show </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> k.paramConfig.siteContact.showBanner;</span></span></code></pre></div><p>The engine will generate <strong>KDefine</strong> type definitions for each configuration of the current site. Under <code>k.paramConfig</code>, you can get intelligent prompts by configuration name and field name.</p><h2 id="data-shape" tabindex="-1">data shape <a class="header-anchor" href="#data-shape" aria-label="Permalink to &quot;data shape&quot;">​</a></h2><ul><li><strong>Schema</strong> is defined in the background and supports <code>string</code>, <code>number</code>, <code>boolean</code>, <code>object</code>, <code>array</code> (and nesting).</li><li><strong>data</strong> must be consistent with Schema; maintained in the background <strong>Edit Data</strong> page or JSON editor.</li><li>Arrays and nested objects are accessed in the same way as ordinary JavaScript objects, such as <code>k.paramConfig.footer.links[0].url</code>.</li></ul><h2 id="when-it-does-not-exist-or-the-value-is-not-filled-in" tabindex="-1">When it does not exist or the value is not filled in <a class="header-anchor" href="#when-it-does-not-exist-or-the-value-is-not-filled-in" aria-label="Permalink to &quot;When it does not exist or the value is not filled in&quot;">​</a></h2><ul><li>Configuration name does not exist, or the configuration does not yet have <code>data</code>: attribute access will result in <strong><code>undefined</code></strong>.</li><li>The script should be judged before use to avoid errors when directly accessing deep properties.</li></ul><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="/kb-docs/cms/content/user-options.html">Param Config (CMS)</a></li><li><a href="/kb-docs/api/site/">k.site</a> — Site Resources</li><li><a href="/kb-docs/api/label/">k.label</a> — multilingual tags</li></ul>`,17)])])}const u=t(i,[["render",s]]);export{g as __pageData,u as default};
